scripts.capture_t0_step:
def _command_for_step(context: CaptureContext, step_id: str) -> tuple[str, ...]:
    values = context.assignments
    python = str(context.repository / '.venv/bin/python')
    if step_id == 'clock-reference':
        return (python, str(context.repository / 'scripts/collect_clock_reference.py'))
    if step_id == 'clock-disable':
        return ('/usr/bin/sudo', '-n', '/usr/sbin/systemsetup', '-setusingnetworktime', 'off')
    if step_id == 'quiet-mac-prep':
        return ('/bin/bash', str(context.repository / 'scripts/quiet_mac_prep.sh'))
    if step_id == 'prewindow-check':
        return context.prewindow_command
    if step_id == 'ledger-readiness':
        return (python, str(context.repository / 'scripts/recover_calibration_ledger.py'), '--ledger', values['CALIBRATION_LEDGER'], '--head-pin', values['LEDGER_HEAD_PIN'], 'readiness', '--phase', 'pre-reserve', '--session-id', values['BRACKET_SESSION_ID'], '--plan', str(context.frozen_plan_path))
    if step_id == 'ledger-reservation':
        return (python, str(context.repository / 'scripts/reserve_calibration_window_bracket.py'), '--ledger', values['CALIBRATION_LEDGER'], '--head-pin', values['LEDGER_HEAD_PIN'], '--session-id', values['BRACKET_SESSION_ID'], '--window-id', values['WINDOW_ID'], '--plan-id', context.plan_id, '--plan-sha256', context.plan_sha256, '--plan', str(context.frozen_plan_path), '--evidence-root-id', values['EVIDENCE_ROOT_ID'], '--runs-root', values['RUNS_ROOT'], '--pre-attempt-id', values['PRE_ATTEMPT_ID'], '--post-attempt-id', values['POST_ATTEMPT_ID'], '--pre-custody-locator', str(Path(values['RUNS_ROOT']) / 'instrument_validation' / values['PRE_ATTEMPT_ID']), '--post-custody-locator', str(Path(values['RUNS_ROOT']) / 'instrument_validation' / values['POST_ATTEMPT_ID']), '--identity-epoch-json', values['IDENTITY_EPOCH_JSON'], '--t1-bindings-json', values['T1_BINDINGS_JSON'], '--execute')
    raise _refuse('evidence_author_t0_capture_usage_invalid', f'unknown T-0 step: {step_id}')

scripts.run_night:
def _bind_argv(kind, job_id, descriptor, request):
    if kind == 'sample':
        return (sys.executable, '-B', '-m', 'joulewise.quiet_admission', '--observation', '--sample-interval-s', str(request['interval']), '--observer-pid', str(request['observer_pid']), '--job-id', job_id, '--result-fd', str(descriptor))
    return (sys.executable, '-B', str(REPO_ROOT / 'scripts/run_night.py'), '_bind-worker', '--kind', kind, '--job-id', job_id, '--result-fd', str(descriptor), '--request', json.dumps(request, separators=(',', ':')))

def _courier_argv(custody_root: Path, plan: NightPlan, courier_bin: Path) -> tuple[str, ...]:
    prompt = (REPO_ROOT / 'docs' / 'process' / 'NIGHT_COURIER_PROMPT.md').read_text(encoding='utf-8')
    prompt = prompt.replace('{custody_root}', str(custody_root)).replace('{plan_id}', plan.plan_id).replace('@@REPO_ROOT@@', str(REPO_ROOT))
    watchdog_path, watchdog_age_s, watchdog_decision = _watchdog_liveness_for_courier(plan)
    prompt += f'\nWatchdog state path: {watchdog_path}\nWatchdog state age seconds: {watchdog_age_s}\nWatchdog last decision: {watchdog_decision}\nYou must include these watchdog fields in the email body. An age greater than 900 seconds, or an unavailable age, means the watchdog is dead.\n'
    cleanup_path = custody_root / 'night/evidence_cleanup.json'
    if cleanup_path.exists():
        prompt += f'\nEvidence cleanup record: {cleanup_path}. Read this existing record and night/evidence_outcome.json; report success, partial evidence or refusal, including unproven cleanup and all refusal documents. Never recreate the record.\n'
    return (str(courier_bin), '-p', prompt, '--output-format', 'text', '--allowedTools', COURIER_ALLOWED_TOOLS)
